document.addEventListener("DOMContentLoaded",init);function init(){const statusEl=document.getElementById("messages-status");const listEl=document.getElementById("messages-list");const stores=collectChatStores();if(stores.length===0){statusEl.textContent="No messages yet.";return}loadInbox(stores,statusEl,listEl)}function collectChatStores(){const stores=[];const prefix="skiri_chat_token_";try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key&&key.indexOf(prefix)===0){const slug=key.slice(prefix.length);const token=localStorage.getItem(key);if(slug&&token){stores.push({storeSlug:slug,customerToken:token,seenAt:inboxSeenAt(slug)})}}}}catch(e){}return stores}async function loadInbox(stores,statusEl,listEl){const stop=startLoadingMessage(statusEl);const res=await Api.post("getCustomerInbox",{stores:stores});stop();if(!res.ok){listEl.innerHTML="";showMessagesLoadFailed(statusEl);return}const convs=res.conversations||[];if(convs.length===0){statusEl.textContent="No messages yet.";return}statusEl.textContent="";listEl.innerHTML=convs.map(threadRow).join("");listEl.querySelectorAll(".inbox-thread").forEach(el=>{el.addEventListener("click",()=>openThread(el.dataset.slug,el.dataset.at))})}function showMessagesLoadFailed(statusEl){const signedIn=typeof CustomerAuth!=="undefined"&&CustomerAuth.getToken();if(signedIn){showLoadFailedMessage(statusEl);return}statusEl.innerHTML='<a href="customer-login.html">Create Your Account now</a> or refresh page'+STATIC_DOTS_HTML}function unreadCountOf(c){if(typeof c.unreadCount==="number")return c.unreadCount;if(c.lastSenderType!=="vendor")return 0;const at=new Date(c.lastMessageAt).getTime();const seenRaw=inboxSeenAt(c.storeSlug);const seen=seenRaw?new Date(seenRaw).getTime():0;return at&&at>seen?1:0}function inboxSeenAt(slug){try{return localStorage.getItem("skiri_inbox_seen_"+slug)||""}catch(e){return""}}function threadRow(c){const count=unreadCountOf(c);const name=c.storeName||c.storeSlug;const avatar=c.storeLogoUrl?`<img class="inbox-avatar-img" src="${escapeHtml(optimizedImageUrl(c.storeLogoUrl,IMG_W.logo))}" alt="" loading="lazy" decoding="async">`:`<span class="inbox-avatar-initials" aria-hidden="true">${escapeHtml(initials(name))}</span>`;const badge=count>0?`<span class="inbox-unread-badge">${count>99?"99+":count}</span>`:"";const unreadLabel=count>0?`<span class="sr-only">${count} unread message${count===1?"":"s"}</span>`:"";return`\n    <button type="button" class="inbox-thread" data-slug="${escapeHtml(c.storeSlug)}" data-at="${escapeHtml(c.lastMessageAt||"")}">\n      <span class="inbox-avatar">${avatar}${badge}</span>\n      <span class="inbox-thread-main">\n        <span class="inbox-thread-name">${escapeHtml(name)}${unreadLabel}</span>\n        <span class="inbox-thread-preview">${escapeHtml(c.lastMessagePreview||"")}</span>\n      </span>\n      <span class="inbox-thread-date">${escapeHtml(inboxDate(c.lastMessageAt))}</span>\n    </button>`}function openThread(slug,at){try{if(at)localStorage.setItem("skiri_inbox_seen_"+slug,at)}catch(e){}window.location.href="store.html?store="+encodeURIComponent(slug)+"&chat=open"}function inboxDate(iso){if(!iso)return"";const d=new Date(iso);const t=d.getTime();if(!t||isNaN(t))return"";const diff=Date.now()-t;const DAY=864e5;if(diff<DAY&&d.getDate()===(new Date).getDate()){return d.toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})}if(diff<7*DAY)return d.toLocaleDateString([],{weekday:"short"});return d.toLocaleDateString()}